CREATE TABLE IF NOT EXISTS field_areas (
 id INTEGER PRIMARY KEY AUTOINCREMENT, course_id TEXT NOT NULL,
 name TEXT NOT NULL, category TEXT NOT NULL CHECK(category IN ('greens','tees','fairways','lawns')),
 geometry_json TEXT NOT NULL, top_bearing REAL NOT NULL DEFAULT 0,
 revision INTEGER NOT NULL DEFAULT 1, last_draft_id TEXT,
 UNIQUE(course_id,name)
);
CREATE TABLE IF NOT EXISTS field_area_drafts (
 id TEXT PRIMARY KEY, course_id TEXT NOT NULL, target_id INTEGER,
 base_revision INTEGER NOT NULL, name TEXT NOT NULL, category TEXT NOT NULL,
 geometry_json TEXT NOT NULL, top_bearing REAL NOT NULL, author_id TEXT NOT NULL,
 created_at TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending',
 reviewed_by TEXT, reviewed_at TEXT
);
CREATE INDEX IF NOT EXISTS field_area_drafts_course ON field_area_drafts(course_id,status,created_at);
